#ifndef _VESC_CONFIG_h
#define _VESC_CONFIG_h

#include <stddef.h>
#include <stdint.h>

/**
 * The VESC sends and takes its motor configuration (mcconf) and app configuration (appconf) as one packed
 * blob, as VESC Tool does. Its layout changes with each firmware release, and its first 4 bytes are a
 * signature that names the layout. VescConfLayouts.cpp (generated by tools/gen_conf_layouts.py from the
 * firmware's confgenerator.c) holds the layout of each supported release, so VescConfig can read and
 * change single fields of a blob by name and leave every other byte exactly as the VESC sent it.
 *
 * Field names are the firmware's mc_configuration / app_configuration member names, which are also the
 * names in VESC Tool's parameter XML, for example "l_current_max" or "timeout_msec". Values are in the
 * firmware's own units (amps, volts, ohms, ERPM, ms), which are not always the units VESC Tool shows:
 * for example, VESC Tool shows foc_motor_r in milliohms but the firmware stores ohms.
 */

enum class VescConfKind : uint8_t { MCCONF, APPCONF };

enum class VescConfType : uint8_t {
	U8,       // 1 byte; bools, enums and small ints. Read back as 0..255.
	U16,
	I16,
	U32,
	I32,
	F16,      // int16 of value * scale
	F32,      // int32 of value * scale
	F32_AUTO, // VESC's 4-byte float encoding
};

struct VescConfField {
	const char * name;
	VescConfType type;
	float scale;
};

struct VescConfLayout {
	VescConfKind kind;
	uint32_t signature;
	/** The firmware release(s) that use this layout, e.g. "6.05/6.06" */
	const char * firmware;
	const VescConfField * fields;
	uint16_t count;
};

extern const VescConfLayout kVescConfLayouts[];
extern const size_t kVescConfLayoutCount;

/** A field name and the value to give it. */
struct VescSetting {
	const char * name;
	double value;
};

class VescConfig
{
	public:
		/** Larger than any supported layout (about 700 bytes). */
		static constexpr size_t MAX_SIZE = 1024;

		VescConfig() {}

		/**
		 * @brief      Takes a blob as read from the VESC (without the packet id).
		 * @return     False if the signature is not a known layout or the length does not match it
		 */
		bool load(VescConfKind kind, const uint8_t * blob, size_t len);

		bool isLoaded() const { return layoutPtr != nullptr; }
		const VescConfLayout * layout() const { return layoutPtr; }
		VescConfKind kind() const { return confKind; }
		/** The signature in the blob, also set when load() failed on an unknown one. */
		uint32_t signature() const { return blobSignature; }
		const uint8_t * data() const { return bytes; }
		size_t size() const { return length; }

		bool has(const char * name) const;

		/** @return False if the field does not exist */
		bool get(const char * name, double & value) const;

		/**
		 * @brief      Encodes value into the field, rounding to its resolution.
		 * @param      changed  - Set to whether the field's bytes changed; may be null
		 * @return     False if the field does not exist or the value does not fit its encoding
		 */
		bool set(const char * name, double value, bool * changed = nullptr);

		/** Finds the layout for a signature, or null. */
		static const VescConfLayout * findLayout(VescConfKind kind, uint32_t signature);

		/** Bytes a field takes in the blob. */
		static size_t fieldSize(VescConfType type);

	private:
		const VescConfField * find(const char * name, size_t & offset) const;
		static double decode(const VescConfField & field, const uint8_t * at);

		const VescConfLayout * layoutPtr = nullptr;
		VescConfKind confKind = VescConfKind::MCCONF;
		uint32_t blobSignature = 0;
		uint8_t bytes[MAX_SIZE];
		size_t length = 0;
};

#endif
